mapper.update:
update user
set money = #{moneyFlowVO.money}
where user_id = #{moneyFlowVO.userId}

update money_flow
set status = 1,type = #{moneyFlowVO.type}
where money_flow_id = #{moneyFlowVO.moneyFlowId}

mapper.select:
select mf.*,c.*,ha.name from money_flow mf
left join consultant c on mf.consultant_id = c.consultant_id
left join hou_admin ha on c.admin_id = ha.admin_id


        mf.tip like concat('%',#{moneyFlowDO.tip},'%')


        and ha.name like concat('%',#{moneyFlowDO.consultantName},'%')


        and c.role = #{moneyFlowDO.consultantRole}


        and mf.type = #{moneyFlowDO.type}


        and mf.status = #{moneyFlowDO.status}
